func ResourceVertexAIRagFileFlatten(d *schema.ResourceData, meta interface{}, res map[string]interface{}, config *transport_tpg.Config, project string, userAgent string, billingProject string, url string, headers http.Header) error {
	var err error

	if err = d.Set("name", flattenVertexAIRagFileName(res["name"], d, config)); err != nil {
		return fmt.Errorf("Error reading RagFile: %s", err)
	}
	if err = d.Set("display_name", flattenVertexAIRagFileDisplayName(res["displayName"], d, config)); err != nil {
		return fmt.Errorf("Error reading RagFile: %s", err)
	}
	if err = d.Set("description", flattenVertexAIRagFileDescription(res["description"], d, config)); err != nil {
		return fmt.Errorf("Error reading RagFile: %s", err)
	}
	if err = d.Set("create_time", flattenVertexAIRagFileCreateTime(res["createTime"], d, config)); err != nil {
		return fmt.Errorf("Error reading RagFile: %s", err)
	}
	if err = d.Set("update_time", flattenVertexAIRagFileUpdateTime(res["updateTime"], d, config)); err != nil {
		return fmt.Errorf("Error reading RagFile: %s", err)
	}
	if err = d.Set("user_metadata", flattenVertexAIRagFileUserMetadata(res["userMetadata"], d, config)); err != nil {
		return fmt.Errorf("Error reading RagFile: %s", err)
	}
	if err = d.Set("file_status", flattenVertexAIRagFileFileStatus(res["fileStatus"], d, config)); err != nil {
		return fmt.Errorf("Error reading RagFile: %s", err)
	}
	if err = d.Set("gcs_source", flattenVertexAIRagFileGcsSource(res["gcsSource"], d, config)); err != nil {
		return fmt.Errorf("Error reading RagFile: %s", err)
	}
	if err = d.Set("google_drive_source", flattenVertexAIRagFileGoogleDriveSource(res["googleDriveSource"], d, config)); err != nil {
		return fmt.Errorf("Error reading RagFile: %s", err)
	}

	return nil
}
